def compute(vars):
    shares = vars["v1"]
    exercise_price = vars["v2"]
    total_value = shares * exercise_price

    return {
        "value": total_value,
        "trace": {
            "shares_purchasable_under_warrant": shares,
            "warrant_exercise_price": exercise_price,
            "total_value": total_value,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "USD"
            }
        }
    }
